import Foundation

/// Ed25519 public key used to authenticate the update manifest envelope.
///
/// The key is the 32-byte raw representation of a `Curve25519.Signing.PublicKey`
/// encoded as base64. It is compiled into the app; the matching private key never
/// leaves the release machine.
public enum UpdatePublicKey {
    /// Generated by `CoolMacRelease keygen` on 2026-10-15. The matching private
    /// key lives only in this machine's login keychain (service
    /// "local.hx10.coolmac.update", account "coolmac"); it is never written to
    /// the project. Losing it means no further update can be signed for builds
    /// that already trust this key — keep a backup of the keychain item.
    public static let base64 = "Hf+9/dYDgTOalIt2NpjbT5yr1ikUiNyv0CKnukRBc4k="
}
